svg.script:
(function() {
  function applyLayout() {
    var w = window.innerWidth || document.documentElement.clientWidth || 1600;
    var root = document.getElementById('rootSvg');
    var desktop = document.getElementById('desktop');
    var tablet = document.getElementById('tablet');
    var mobile = document.getElementById('mobile');

    desktop.style.display = 'none';
    tablet.style.display = 'none';
    mobile.style.display = 'none';

    if (w <= 640) {
      root.setAttribute('viewBox','0 0 600 3000');
      root.style.height = 'auto';
      root.style.aspectRatio = '600 / 3000';
      mobile.style.display = 'inline';
    } else if (w <= 1100) {
      root.setAttribute('viewBox','0 0 1000 1850');
      root.style.height = 'auto';
      root.style.aspectRatio = '1000 / 1850';
      tablet.style.display = 'inline';
    } else {
      root.setAttribute('viewBox','0 0 1600 1350');
      root.style.height = 'auto';
      root.style.aspectRatio = '1600 / 1350';
      desktop.style.display = 'inline';
    }
  }
  applyLayout();
  window.addEventListener('load', applyLayout);
  window.addEventListener('resize', applyLayout);
  window.addEventListener('orientationchange', applyLayout);
})();
